mapper.update:
UPDATE medications
SET
efficacy = #{efficacy},
usage_dosage = #{usageDosage},
item_image_url = #{itemImageUrl},
updated_at = SYSDATE
WHERE
medication_id = #{itemSeq}
AND (
/* * 효능이 변경된 경우 */ NVL(efficacy, '#NULL#') <> NVL(#{efficacy}, '#NULL#')
OR
/* * 사용법이 변경된 경우 */ NVL(usage_dosage, '#NULL#') <> NVL(#{usageDosage}, '#NULL#')
OR
/* * 이미지 URL이 변경된 경우 */ NVL(item_image_url, '#NULL#') <> NVL(#{itemImageUrl}, '#NULL#')
)
